// Rows are [question, correct answer, three distractors, correct option index].
const makeSeasonTwoQuestions = (rows) => rows.map(([q, correct, distractors, answer]) => {
    const options = [...distractors];
    options.splice(answer, 0, correct);
    return { q, options, answer };
});

